_choice_ansible_inventory_group() {
    _helper_ansible_inventory_items group
}

_choice_ansible_inventory_host() {
    _helper_ansible_inventory_items host
}

_choice_ansible_inventory_target() {
    _helper_ansible_inventory_items target
}

_helper_ansible_inventory_items() {
    local inv=() item list
    for item in "${argc_inventory_file[@]:-}" "${argc_inventory[@]:-}"; do
        [[ -n "$item" ]] && inv+=(-i "$item")
    done
    list=$(ansible-inventory "${inv[@]}" --list 2>/dev/null) || return 0
    case "$1" in
    host)
        printf '%s\n' "$list" | jq -b -r '(.. | objects | (.hosts? // empty)[]), (.["_meta"]?.hostvars? // {} | keys[])'
        ;;
    group)
        printf '%s\n' "$list" | jq -b -r '(keys[] | select(. != "_meta")), (.. | objects | (.children? // empty)[])'
        ;;
    target)
        printf '%s\n' "$list" | jq -b -r '(keys[] | select(. != "_meta")), (.. | objects | (.children? // empty)[]), (.. | objects | (.hosts? // empty)[]), (.["_meta"]?.hostvars? // {} | keys[])'
        ;;
    esac
}
